import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.D46keoNO.js";const g=JSON.parse('{"title":"Translation Services","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/services.md","filePath":"en/guide/services.md","lastUpdated":1785141565000}'),o={name:"en/guide/services.md"};function l(n,e,s,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="translation-services" tabindex="-1">Translation Services <a class="header-anchor" href="#translation-services" aria-label="Permalink to &quot;Translation Services&quot;">​</a></h1><h2 id="service-list" tabindex="-1">Service List <a class="header-anchor" href="#service-list" aria-label="Permalink to &quot;Service List&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Auth</th><th>Cost</th><th>Notes</th></tr></thead><tbody><tr><td>Pinyin</td><td>None</td><td>Free</td><td>Default service and final fallback; converts CJK characters to pinyin, works offline</td></tr><tr><td>ChatGPT / OpenAI</td><td>API Key</td><td>Pay-as-you-go</td><td>Custom baseUrl/model, compatible with third-party OpenAI APIs</td></tr><tr><td>Google Translate</td><td>API Key</td><td>Pay-as-you-go</td><td>Official Cloud Translation API, requires a Google Cloud API key</td></tr><tr><td>Bing / Azure Translator</td><td>API Key</td><td>Pay-as-you-go</td><td>Requires an Azure account, custom region supported</td></tr><tr><td>DeepLX</td><td>Local deployment</td><td>Free</td><td>Automatic health checks, custom endpoint supported</td></tr><tr><td>Baidu Translate</td><td>APP_ID + Key</td><td>Pay-as-you-go</td><td>Requires a Baidu Translate open platform account</td></tr><tr><td>Tencent Translator</td><td>SecretId + SecretKey</td><td>Pay-as-you-go</td><td>Custom region supported (default ap-guangzhou)</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">About the config value</p><p>In the <code>translationService</code> setting, <code>copilot</code> is a legacy value that actually maps to the <strong>Pinyin service</strong>.</p></div><h2 id="getting-api-keys" tabindex="-1">Getting API Keys <a class="header-anchor" href="#getting-api-keys" aria-label="Permalink to &quot;Getting API Keys&quot;">​</a></h2><h3 id="openai" tabindex="-1">OpenAI <a class="header-anchor" href="#openai" aria-label="Permalink to &quot;OpenAI&quot;">​</a></h3><ol><li>Visit <a href="https://platform.openai.com/" target="_blank" rel="noreferrer">OpenAI Platform</a></li><li>Sign up / log in</li><li>Open the <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">API Keys page</a></li><li>Click &quot;Create new secret key&quot;</li><li>Copy the key (format: <code>sk-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx</code>)</li><li>(Optional) set a custom <code>baseUrl</code> for a third-party OpenAI-compatible API</li><li>(Optional) set a custom <code>model</code> (default <code>gpt-3.5-turbo</code>)</li></ol><h3 id="google-translate" tabindex="-1">Google Translate <a class="header-anchor" href="#google-translate" aria-label="Permalink to &quot;Google Translate&quot;">​</a></h3><ol><li>Visit <a href="https://console.cloud.google.com/" target="_blank" rel="noreferrer">Google Cloud Console</a></li><li>Sign up / log in and create a project</li><li>Enable the <a href="https://console.cloud.google.com/apis/library/translate.googleapis.com" target="_blank" rel="noreferrer">Cloud Translation API</a></li><li>Create an API key under &quot;APIs &amp; Services → Credentials&quot;</li><li>Paste the key into the extension settings</li></ol><h3 id="bing-azure-translator" tabindex="-1">Bing / Azure Translator <a class="header-anchor" href="#bing-azure-translator" aria-label="Permalink to &quot;Bing / Azure Translator&quot;">​</a></h3><ol><li>Visit <a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azure Portal</a></li><li>Sign up / log in</li><li>Create a <a href="https://portal.azure.com/#create/Microsoft.CognitiveServicesMultiService" target="_blank" rel="noreferrer">Translator</a> resource</li><li>Open the resource → &quot;Keys and Endpoint&quot;</li><li>Copy the API key and region</li></ol><h3 id="deeplx" tabindex="-1">DeepLX <a class="header-anchor" href="#deeplx" aria-label="Permalink to &quot;DeepLX&quot;">​</a></h3><ol><li>Visit <a href="https://deeplx.owo.network/" target="_blank" rel="noreferrer">DeepLX</a> or <a href="https://github.com/OwO-Network/DeepLX" target="_blank" rel="noreferrer">DeepLX on GitHub</a></li><li>Deploy the service locally following the instructions</li><li>Default endpoint: <code>http://127.0.0.1:1188</code> (custom <code>baseUrl</code> supported)</li><li>The extension performs automatic health checks (60s cache)</li><li>No further configuration needed</li></ol><h3 id="baidu-translate" tabindex="-1">Baidu Translate <a class="header-anchor" href="#baidu-translate" aria-label="Permalink to &quot;Baidu Translate&quot;">​</a></h3><ol><li>Visit the <a href="https://fanyi-api.baidu.com/" target="_blank" rel="noreferrer">Baidu Translate Open Platform</a></li><li>Sign up / log in</li><li>Open the <a href="https://fanyi-api.baidu.com/aitrans" target="_blank" rel="noreferrer">console</a></li><li>Enable the General Translation API</li><li>Obtain the APP_ID and Secret Key</li></ol><h3 id="tencent-translator" tabindex="-1">Tencent Translator <a class="header-anchor" href="#tencent-translator" aria-label="Permalink to &quot;Tencent Translator&quot;">​</a></h3><ol><li>Visit <a href="https://console.cloud.tencent.com/" target="_blank" rel="noreferrer">Tencent Cloud</a></li><li>Sign up / log in</li><li>Enable <a href="https://console.cloud.tencent.com/tmt" target="_blank" rel="noreferrer">Machine Translation</a></li><li>Open <a href="https://console.cloud.tencent.com/cam/capi" target="_blank" rel="noreferrer">API Key Management</a></li><li>Obtain the SecretId and SecretKey</li><li>(Optional) set a custom <code>region</code> (default <code>ap-guangzhou</code>)</li></ol><h2 id="switching-services" tabindex="-1">Switching Services <a class="header-anchor" href="#switching-services" aria-label="Permalink to &quot;Switching Services&quot;">​</a></h2><h3 id="shortcut" tabindex="-1">Shortcut <a class="header-anchor" href="#shortcut" aria-label="Permalink to &quot;Shortcut&quot;">​</a></h3><p>Press <code>Alt+Shift+S</code> to switch quickly.</p><h3 id="command-palette" tabindex="-1">Command Palette <a class="header-anchor" href="#command-palette" aria-label="Permalink to &quot;Command Palette&quot;">​</a></h3><ol><li>Press <code>Ctrl+Shift+P</code></li><li>Type &quot;切换翻译服务&quot; (Switch Translation Service)</li><li>Pick a service</li></ol><h3 id="context-menu" tabindex="-1">Context Menu <a class="header-anchor" href="#context-menu" aria-label="Permalink to &quot;Context Menu&quot;">​</a></h3><p>Right-click in the editor → &quot;切换翻译服务&quot;.</p><div class="tip custom-block"><p class="custom-block-title">Unconfigured services</p><p>Picking a service that requires a key but is not configured prompts you to open the settings, jumping straight to <code>variableTranslator.services</code>.</p></div><h2 id="service-comparison" tabindex="-1">Service Comparison <a class="header-anchor" href="#service-comparison" aria-label="Permalink to &quot;Service Comparison&quot;">​</a></h2><h3 id="pinyin" tabindex="-1">Pinyin <a class="header-anchor" href="#pinyin" aria-label="Permalink to &quot;Pinyin&quot;">​</a></h3><ul><li><strong>Pros</strong>: zero configuration, works offline, converts CJK characters to pinyin</li><li><strong>Cons</strong>: pinyin conversion only, not real translation</li><li><strong>Best for</strong>: out-of-the-box default and the final fallback when everything else fails</li></ul><h3 id="openai-1" tabindex="-1">OpenAI <a class="header-anchor" href="#openai-1" aria-label="Permalink to &quot;OpenAI&quot;">​</a></h3><ul><li><strong>Pros</strong>: high quality, understands programming context, custom baseUrl/model</li><li><strong>Cons</strong>: requires an API key, pay-as-you-go</li><li><strong>Best for</strong>: high-quality translation; third-party compatible APIs can lower costs</li></ul><h3 id="google-translate-1" tabindex="-1">Google Translate <a class="header-anchor" href="#google-translate-1" aria-label="Permalink to &quot;Google Translate&quot;">​</a></h3><ul><li><strong>Pros</strong>: official API, stable quality, no CAPTCHA / IP-ban risk</li><li><strong>Cons</strong>: requires a Google Cloud account and API key, pay-as-you-go</li><li><strong>Best for</strong>: reliable Google translation quality</li></ul><h3 id="bing-azure-translator-1" tabindex="-1">Bing / Azure Translator <a class="header-anchor" href="#bing-azure-translator-1" aria-label="Permalink to &quot;Bing / Azure Translator&quot;">​</a></h3><ul><li><strong>Pros</strong>: official Microsoft API, stable quality, free tier available</li><li><strong>Cons</strong>: requires an Azure account</li><li><strong>Best for</strong>: users who already have an Azure account</li></ul><h3 id="deeplx-1" tabindex="-1">DeepLX <a class="header-anchor" href="#deeplx-1" aria-label="Permalink to &quot;DeepLX&quot;">​</a></h3><ul><li><strong>Pros</strong>: local deployment, free, automatic health checks</li><li><strong>Cons</strong>: requires deploying the service yourself</li><li><strong>Best for</strong>: privacy-conscious or cost-free usage</li></ul><h3 id="baidu-translate-1" tabindex="-1">Baidu Translate <a class="header-anchor" href="#baidu-translate-1" aria-label="Permalink to &quot;Baidu Translate&quot;">​</a></h3><ul><li><strong>Pros</strong>: fast within China</li><li><strong>Cons</strong>: account registration required</li><li><strong>Best for</strong>: users in China</li></ul><h3 id="tencent-translator-1" tabindex="-1">Tencent Translator <a class="header-anchor" href="#tencent-translator-1" aria-label="Permalink to &quot;Tencent Translator&quot;">​</a></h3><ul><li><strong>Pros</strong>: fast within China, custom region</li><li><strong>Cons</strong>: requires a Tencent Cloud account</li><li><strong>Best for</strong>: users in China</li></ul><h2 id="fallback-chain" tabindex="-1">Fallback Chain <a class="header-anchor" href="#fallback-chain" aria-label="Permalink to &quot;Fallback Chain&quot;">​</a></h2><p>When a translation call fails, the extension falls back automatically by the <code>servicePriority</code> order:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Current service fails → next service by priority → all fail → Pinyin</span></span></code></pre></div><ul><li>The currently selected service is always tried first, then the priority list in order</li><li>Every service has a <strong>10-second timeout</strong>; on timeout the next service is tried</li><li>The global translation timeout is also 10 seconds, after which Pinyin takes over</li><li>Pinyin is the final safety net — translation <strong>never fails</strong></li></ul><h2 id="automatic-language-detection" tabindex="-1">Automatic Language Detection <a class="header-anchor" href="#automatic-language-detection" aria-label="Permalink to &quot;Automatic Language Detection&quot;">​</a></h2><p>All services detect the source language automatically. Supported:</p><ul><li>Chinese</li><li>Japanese</li><li>Korean</li><li>Russian</li><li>Any other non-English characters</li></ul>',47)])])}const p=t(o,[["render",l]]);export{g as __pageData,p as default};
